script:
// ─────────────────────────────────────────────────────────
// SIDEBAR
// ─────────────────────────────────────────────────────────
const sidebar = document.getElementById('sidebar');
const progressLine = document.getElementById('progressLine');
const overlay = document.getElementById('sbOverlay');
const isMobile = () => window.innerWidth < 768;
const saved = localStorage.getItem('sb-state');
if (saved === 'collapsed' && !isMobile()) {
  sidebar.classList.add('collapsed');
  progressLine.classList.add('visible');
}
function toggleSidebar() {
  if (isMobile()) {
    const o = sidebar.classList.toggle('open');
    overlay.classList.toggle('visible', o);
    return;
  }
  const c = sidebar.classList.toggle('collapsed');
  progressLine.classList.toggle('visible', c);
  localStorage.setItem('sb-state', c ? 'collapsed' : 'expanded');
}

// ─────────────────────────────────────────────────────────
// SECTION NAV HIGHLIGHT
// ─────────────────────────────────────────────────────────
const la = document.getElementById('lessonArea');
const secIds = [...document.querySelectorAll('section[id]')].map(s => s.id);
document.querySelectorAll('.section-nav a').forEach(a => {
  a.addEventListener('click', function(e) {
    e.preventDefault();
    const target = document.getElementById(this.getAttribute('href').slice(1));
    if (target) la.scrollTo({ top: target.offsetTop - 48, behavior: 'smooth' });
  });
});
la.addEventListener('scroll', () => {
  const st = la.scrollTop + 60;
  let cur = secIds[0];
  secIds.forEach(id => {
    const el = document.getElementById(id);
    if (el && el.offsetTop <= st) cur = id;
  });
  document.querySelectorAll('.section-nav a').forEach(a => {
    a.classList.toggle('active', a.getAttribute('href') === '#' + cur);
  });
});

// ─────────────────────────────────────────────────────────
// EXPANSION BUILDER
// ─────────────────────────────────────────────────────────
const PRESETS = {
  lin: {
    title: 'T(n) = T(n−1) + 1, T(1) = 1',
    steps: [
      { label: 'Definição original', math: 'T(n) = T(n−1) + 1', explain: 'A recorrência descreve: processar n itens custa processar n−1 itens mais 1 operação extra.' },
      { label: 'Substituição k=1', math: 'T(n) = [T(n−2) + 1] + 1 = T(n−2) + 2', explain: 'Aplicamos a definição de T(n−1): substituímos T(n−1) por T(n−2)+1. Acumulamos 2 unidades de custo.' },
      { label: 'Substituição k=2', math: 'T(n) = T(n−3) + 3', explain: 'Repetimos: T(n−2) = T(n−3)+1. Padrão emergindo: a cada passo, o índice cai 1 e o custo acumulado sobe 1.' },
      { label: 'Padrão geral após k passos', math: 'T(n) = T(n−k) + k', explain: 'Generalizando: após k substituições temos T(n) = T(n−k) + k. Isso vale para qualquer k ≤ n−1.' },
      { label: 'Encontrando o caso base', math: 'n − k = 1  →  k = n − 1', explain: 'O caso base é T(1). Queremos n−k = 1, portanto k = n−1. Substituímos na fórmula geral.' },
      { label: 'Resultado final', math: 'T(n) = T(1) + (n−1) = 1 + n − 1 = n', explain: 'T(n) = n → O(n). Intuitivo: buscamos 1 elemento, depois 2, depois 3... no total somamos 1+1+1+... = n vezes.', highlight: true }
    ]
  },
  log: {
    title: 'T(n) = T(n/2) + 1, T(1) = 1',
    steps: [
      { label: 'Definição original', math: 'T(n) = T(n/2) + 1', explain: 'Descreve a busca binária: processar n elementos custa processar n/2 elementos (metade descartada) mais 1 comparação.' },
      { label: 'Substituição k=1', math: 'T(n) = T(n/4) + 1 + 1 = T(n/4) + 2', explain: 'Aplicamos a definição em T(n/2): T(n/2) = T(n/4)+1. Temos agora T(n) = T(n/2²) + 2.' },
      { label: 'Substituição k=2', math: 'T(n) = T(n/8) + 3', explain: 'Repetindo: T(n/4) = T(n/8)+1. Perceba: n é dividido por 2 mais uma vez, e o custo acumulado sobe mais 1.' },
      { label: 'Padrão geral após k passos', math: 'T(n) = T(n / 2ᵏ) + k', explain: 'Generalizando: após k substituições, temos T(n) = T(n/2ᵏ) + k. A cada passo, n é dividido por 2 e acumulamos +1.' },
      { label: 'Encontrando o caso base', math: 'n / 2ᵏ = 1  →  2ᵏ = n  →  k = log₂(n)', explain: 'Queremos chegar em T(1). Isso ocorre quando n/2ᵏ = 1, ou seja, 2ᵏ = n. Por definição de logaritmo, k = log₂(n).' },
      { label: 'Resultado final', math: 'T(n) = T(1) + log₂(n) = 1 + log₂(n)', explain: 'T(n) = 1 + log₂(n) → O(log n). Para n = 1.000.000, isso é ≈ 20 passos. Dobrar n adiciona apenas 1 passo.', highlight: true }
    ]
  },
  nlogn: {
    title: 'T(n) = 2T(n/2) + n, T(1) = 1',
    steps: [
      { label: 'Definição original', math: 'T(n) = 2T(n/2) + n', explain: 'Merge Sort: dividimos em 2 metades (custo 2T(n/2)) e juntamos as metades ordenadas (custo n).' },
      { label: 'Substituição k=1', math: 'T(n) = 2[2T(n/4) + n/2] + n = 4T(n/4) + n + n = 4T(n/4) + 2n', explain: 'Aplicamos a definição em cada T(n/2): T(n/2) = 2T(n/4) + n/2. Expandindo: 2 × [2T(n/4) + n/2] = 4T(n/4) + n. Somando o +n do nível 0: 4T(n/4) + 2n.' },
      { label: 'Substituição k=2', math: 'T(n) = 8T(n/8) + 3n', explain: 'Aplicamos de novo: 4T(n/4) = 4[2T(n/8) + n/4] = 8T(n/8) + n. Somando o 2n acumulado: 8T(n/8) + 3n.' },
      { label: 'Padrão geral após k passos', math: 'T(n) = 2ᵏ · T(n/2ᵏ) + k · n', explain: 'Generalizando: 2ᵏ subproblemas de tamanho n/2ᵏ, cada nível contribuindo exatamente n de trabalho. O fator k vem de k níveis somados.' },
      { label: 'Encontrando o caso base', math: 'n / 2ᵏ = 1  →  k = log₂(n)', explain: 'Base quando n/2ᵏ = 1 → k = log₂(n). Temos 2^log₂(n) = n subproblemas de tamanho 1.' },
      { label: 'Resultado final', math: 'T(n) = n · T(1) + log₂(n) · n = n + n log₂(n)  →  Θ(n log n)', explain: 'log₂(n) níveis × n trabalho por nível = n log₂n. O +n é absorvido. Confirma o que você viu na árvore de recorrência.', highlight: true }
    ]
  },
  exp: {
    title: 'T(n) = 2T(n−1), T(1) = 1',
    steps: [
      { label: 'Definição original', math: 'T(n) = 2T(n−1)', explain: 'Aparece no cálculo ingênuo de Fibonacci e na Torre de Hanói. Duas chamadas recursivas, cada uma de tamanho n−1. Nota: o TM não se aplica (redução é n−1, não n/b).' },
      { label: 'Substituição k=1', math: 'T(n) = 2 · [2T(n−2)] = 4T(n−2) = 2²T(n−2)', explain: 'Aplicamos T(n−1) = 2T(n−2). O coeficiente 2 duplica a cada passo — isso é o sinal de crescimento exponencial.' },
      { label: 'Substituição k=2', math: 'T(n) = 2³T(n−3)', explain: 'Repetindo: T(n−2) = 2T(n−3), portanto 4T(n−2) = 8T(n−3) = 2³T(n−3). Cada passo dobra o coeficiente.' },
      { label: 'Padrão geral após k passos', math: 'T(n) = 2ᵏ · T(n−k)', explain: 'Generalizando: após k substituições, temos 2ᵏ chamadas para subproblemas de tamanho n−k.' },
      { label: 'Encontrando o caso base', math: 'n − k = 1  →  k = n − 1', explain: 'Base quando n−k = 1 → k = n−1. Nesse ponto temos 2^(n−1) chamadas ao caso base.' },
      { label: 'Resultado final', math: 'T(n) = 2^(n−1) · T(1) = 2^(n−1)  →  Θ(2ⁿ)', explain: 'T(n) = 2^(n−1) → O(2ⁿ). Para n=50: ~10¹⁵ operações. É por isso que Fibonacci ingênuo é impraticável e precisa de memoização.', highlight: true }
    ]
  }
};

let currentPreset = 'lin';
let currentStep = -1;

function setPreset(key) {
  currentPreset = key;
  currentStep = -1;
  document.querySelectorAll('.exp-preset-btn').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('.exp-preset-btn').forEach(b => {
    const onclick = b.getAttribute('onclick');
    if (onclick && onclick.includes("'" + key + "'")) b.classList.add('active');
  });
  renderExpSteps();
}

function renderExpSteps() {
  const preset = PRESETS[currentPreset];
  const container = document.getElementById('expStepsContainer');
  let html = `<div style="font-family:var(--fm);font-size:.78rem;color:var(--muted);margin-bottom:.6rem;padding:.4rem .6rem;background:var(--n50);border-radius:6px">${preset.title}</div>`;
  preset.steps.forEach((s, i) => {
    const show = i <= currentStep;
    const cls = `exp-step${s.highlight ? ' highlight-step' : ''}${show ? ' show' : ''}`;
    html += `<div class="${cls}" id="expStep${i}">
      <div class="exp-step-label">${s.label}</div>
      <div class="exp-step-math">${s.math}</div>
      <div class="exp-step-explain">${s.explain}</div>
    </div>`;
  });
  container.innerHTML = html;
  updateExpCounter();
}

function updateExpCounter() {
  const total = PRESETS[currentPreset].steps.length;
  const shown = Math.max(0, currentStep + 1);
  document.getElementById('expCounter').textContent = `Passo ${shown} / ${total}`;
  const btn = document.getElementById('expNextBtn');
  if (btn) btn.disabled = currentStep >= total - 1;
}

function expNext() {
  const total = PRESETS[currentPreset].steps.length;
  if (currentStep < total - 1) {
    currentStep++;
    const el = document.getElementById('expStep' + currentStep);
    if (el) {
      el.classList.add('show');
      el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
    updateExpCounter();
  }
}

function expRunAll() {
  const total = PRESETS[currentPreset].steps.length;
  currentStep = total - 1;
  renderExpSteps();
}

function expReset() {
  currentStep = -1;
  renderExpSteps();
}

// ─────────────────────────────────────────────────────────
// TREE OF RECURRENCE
// ─────────────────────────────────────────────────────────
let treeN = 8;
let treeLevel = -1;

function setTreeN(n) {
  treeN = n;
  treeLevel = -1;
  ['4','8','16','32'].forEach(v => {
    const btn = document.getElementById('treeN' + v + 'Btn');
    if (btn) btn.classList.toggle('active', parseInt(v) === n);
  });
  renderTreeTable();
}

function treeNext() {
  const maxLevel = Math.log2(treeN);
  if (treeLevel < maxLevel) {
    treeLevel++;
    renderTreeTable();
  }
}

function treeRunAll() {
  treeLevel = Math.log2(treeN);
  renderTreeTable();
}

function treeReset() {
  treeLevel = -1;
  renderTreeTable();
}

function renderTreeTable() {
  const container = document.getElementById('treeTableContainer');
  if (!container) return;
  const mergeLevels = Math.log2(treeN);
  let html = `<table class="tree-table"><thead><tr>
    <th>Nível</th><th>Nós</th><th>Tamanho/nó</th><th>Trabalho/nó</th><th style="min-width:140px">Total do nível</th>
  </tr></thead><tbody>`;
  let cumWork = 0;
  for (let lv = 0; lv <= mergeLevels; lv++) {
    const nodes = Math.pow(2, lv);
    const size = treeN / nodes;
    const isBase = lv === mergeLevels;
    const workPerNode = isBase ? 0 : size;
    const totalWork = nodes * workPerNode;
    const visible = lv <= treeLevel;
    if (visible) cumWork += totalWork;
    const rowStyle = isBase
      ? 'style="background:#e8f5ee"'
      : (lv % 2 === 1 ? 'style="background:#f5f8ff"' : '');
    const totalCell = !visible
      ? '<span style="color:var(--n300)">—</span>'
      : (isBase
          ? '<span style="color:var(--green);font-weight:700">0 (base)</span>'
          : `<span style="color:var(--accent);font-weight:700">${treeN}</span>`);
    html += `<tr ${rowStyle}>
      <td>${lv}</td>
      <td>${visible ? nodes : '<span style="color:var(--n300)">—</span>'}</td>
      <td>${visible ? size : '<span style="color:var(--n300)">—</span>'}</td>
      <td>${visible ? (isBase ? '0' : size) : '<span style="color:var(--n300)">—</span>'}</td>
      <td>${totalCell}</td>
    </tr>`;
  }
  const isComplete = treeLevel >= mergeLevels;
  html += `<tr class="total-row">
    <td colspan="4">${isComplete
      ? `✓ Total: ${mergeLevels} níveis × ${treeN} = `
      : `Em progresso (${Math.max(0, treeLevel + 1)} de ${mergeLevels + 1} níveis revelados)`
    }</td>
    <td>${isComplete
      ? `<strong>${cumWork}</strong> = Θ(${treeN} × log₂${treeN})`
      : cumWork > 0 ? `${cumWork} até agora` : '—'
    }</td>
  </tr>`;
  html += '</tbody></table>';
  if (isComplete) {
    const seq = Array.from({ length: mergeLevels + 1 }, (_, i) => treeN / Math.pow(2, i)).join(' → ');
    html += `<div class="callout success" style="margin-top:.6rem">
      <strong>De onde vem o log₂(${treeN}) = ${mergeLevels}?</strong> Dividindo por 2 até chegar em 1: ${seq}.
      São <strong>${mergeLevels} divisões</strong>. Cada um dos ${mergeLevels} níveis de merge faz exatamente <strong>${treeN} operações</strong>.
      Custo total = ${treeN} × ${mergeLevels} = <strong>${cumWork} = Θ(n log n)</strong>.
    </div>`;
  }
  container.innerHTML = html;
}

// ─────────────────────────────────────────────────────────
// MASTER THEOREM CALCULATOR
// ─────────────────────────────────────────────────────────
const MASTER_PRESETS = {
  merge:   { a: 2, b: 2, f: '1',   label: 'Merge Sort: T(n)=2T(n/2)+n' },
  binary:  { a: 1, b: 2, f: '0',   label: 'Busca Binária: T(n)=T(n/2)+1' },
  strassen:{ a: 7, b: 2, f: '2',   label: 'Strassen: T(n)=7T(n/2)+n²' },
  caso1:   { a: 4, b: 2, f: '1',   label: 'Caso 1 puro: T(n)=4T(n/2)+n' },
  caso2b:  { a: 4, b: 2, f: '2',   label: 'Caso 2 variante: T(n)=4T(n/2)+n²' },
  caso3:   { a: 4, b: 2, f: '3',   label: 'Caso 3 puro: T(n)=4T(n/2)+n³' }
};

function setMasterPreset(key) {
  const p = MASTER_PRESETS[key];
  document.getElementById('mcA').value = p.a;
  document.getElementById('mcB').value = p.b;
  document.getElementById('mcF').value = p.f;
  calcMaster();
}

function logBase(a, b) { return Math.log(a) / Math.log(b); }

function fLabel(exp) {
  if (exp === '0') return 'O(1)';
  if (exp === '0.5') return 'O(√n)';
  if (exp === '1') return 'O(n)';
  if (exp === '1.5') return 'O(n^1.5)';
  if (exp === '2') return 'O(n²)';
  if (exp === '3') return 'O(n³)';
  return 'O(n^' + exp + ')';
}

function calcMaster() {
  const a = parseFloat(document.getElementById('mcA').value);
  const b = parseFloat(document.getElementById('mcB').value);
  const fExp = parseFloat(document.getElementById('mcF').value);
  const box = document.getElementById('mcResultBox');
  if (!box) return;

  if (a < 1 || b <= 1) {
    box.className = 'mc-result-box show';
    box.innerHTML = '<div style="color:#ff8a80;font-size:.88rem">⚠ a deve ser ≥ 1 e b deve ser > 1.</div>';
    return;
  }

  const logBA = logBase(a, b);
  const logBAr = Math.round(logBA * 100) / 100;
  const fExpN = fExp;

  let caseNum, resultText, answerClass, explanation;
  const EPS = 0.0001;

  if (fExpN < logBA - EPS) {
    caseNum = 1;
    const exp = logBAr % 1 === 0 ? logBAr.toFixed(0) : logBAr.toFixed(2);
    resultText = `Θ(n^${exp})`;
    answerClass = 'mc-ans-1';
    explanation = `f(n) = O(n^${fExpN}) cresce mais devagar que n^log_b(a) = n^${logBAr}. As <strong>folhas dominam</strong>. O custo total é determinado pela última camada da árvore.`;
  } else if (Math.abs(fExpN - logBA) <= EPS) {
    caseNum = 2;
    const exp = logBAr % 1 === 0 ? logBAr.toFixed(0) : logBAr.toFixed(2);
    resultText = `Θ(n^${exp} · log n)`;
    answerClass = 'mc-ans-2';
    explanation = `f(n) = O(n^${fExpN}) cresce igual a n^log_b(a) = n^${logBAr}. <strong>Empate</strong> — cada um dos log n níveis contribui igualmente. O log n extra vem da soma de log n parcelas iguais.`;
  } else {
    caseNum = 3;
    const exp = fExpN % 1 === 0 ? fExpN.toFixed(0) : fExpN.toFixed(2);
    resultText = `Θ(n^${exp})`;
    answerClass = 'mc-ans-3';
    explanation = `f(n) = O(n^${fExpN}) cresce mais rápido que n^log_b(a) = n^${logBAr}. A <strong>raiz domina</strong>. O custo total é determinado pelo trabalho do nível 0 (a raiz da árvore).`;
  }

  box.className = 'mc-result-box show';
  box.innerHTML = `
    <div class="mc-res-step">Entrada: <span>a = ${a}, b = ${b}, f(n) = ${fLabel(String(fExp))}</span></div>
    <div class="mc-res-step">Calcular: <span>log_b(a) = log_${b}(${a}) = ${logBAr}</span></div>
    <div class="mc-res-step">Comparar: <span>n^log_b(a) = n^${logBAr}</span> vs <span>f(n) = ${fLabel(String(fExp))}</span></div>
    <div class="mc-res-step">→ <strong style="color:white">Caso ${caseNum}:</strong> ${explanation}</div>
    <div class="mc-res-answer ${answerClass}">T(n) = ${resultText}</div>
  `;
}

// ─────────────────────────────────────────────────────────
// QUIZ
// ─────────────────────────────────────────────────────────
const QUIZ_DATA = {
  q1: {
    correct: 'B',
    ok: 'T(n) = T(n/2) + c: a cada passo a entrada é dividida por 2 e adicionamos c (constante). Após k passos: T(n) = T(n/2ᵏ) + k·c. Quando n/2ᵏ = 1 → k = log₂(n). Portanto T(n) = T(1) + c·log₂(n) = O(log n).',
    why: {
      A: 'O(1) significaria custo constante independente de n — mas a recorrência tem chamadas recursivas que dependem de n. Só seria O(1) se não houvesse recursão.',
      C: 'O(n) ocorre quando você faz n operações no total (ex: loop de n iterações). Aqui, cada expansão divide n por 2 — são apenas log n passos, não n.',
      D: 'O(n log n) seria o custo se você tivesse n trabalho POR nível (como T(n)=2T(n/2)+n). Aqui o trabalho é apenas c (constante) por nível, não n.'
    }
  },
  q2: {
    correct: 'B',
    ok: 'a=2, b=2. log_b(a) = log₂(2) = 1. n^log_b(a) = n¹ = n. f(n) = n = n¹. Como f(n) = Θ(n^log_b(a)) — eles crescem igual — aplica-se o Caso 2. Resultado: Θ(n¹ · log n) = Θ(n log n).',
    why: {
      A: 'Caso 1 exigiria que f(n) crescesse MAIS DEVAGAR que n^log_b(a) = n. Mas f(n) = n cresce exatamente igual a n — não mais devagar.',
      C: 'Caso 3 exigiria que f(n) crescesse MAIS RÁPIDO que n^log_b(a) = n. Mas n = n — são iguais, não há quem cresça mais rápido.',
      D: 'O TM se aplica perfeitamente: a=2 (inteiro ≥ 1), b=2 (>1), f(n)=n (polinomial). Todos os pré-requisitos são satisfeitos.'
    }
  },
  q3: {
    correct: 'C',
    ok: 'a=4, b=2. log₂(4) = 2. n^2 = n². f(n) = n² = n². Como f(n) = Θ(n^2) = Θ(n^log_b(a)) — empate — aplica-se o Caso 2. Resultado: Θ(n² · log n) = Θ(n² log n).',
    why: {
      A: 'Θ(n²) seria o resultado do Caso 1 (folhas dominam) ou Caso 3 (raiz domina) com f(n)=n². Mas aqui f(n) e n^log_b(a) são iguais → Caso 2, que adiciona o fator log n.',
      B: 'Θ(n³) exigiria log_b(a) = 3 ou f(n) = n³. Aqui log₂(4) = 2 e f(n) = n² — nenhum dos dois é n³.',
      D: 'Θ(n log n) é o resultado do Merge Sort (a=2, b=2, f(n)=n). Aqui a=4 dá log₂(4)=2, então o expoente base é n², não n.'
    }
  },
  q4: {
    correct: 'D',
    ok: 'a=4, b=2. log₂(4) = 2. n^log_b(a) = n². f(n) = n³. Como n³ cresce MAIS RÁPIDO que n² (n³/n² = n → ∞), temos Caso 3. Resultado: Θ(f(n)) = Θ(n³).',
    why: {
      A: 'Caso 1 com Θ(n²) seria correto SE f(n) crescesse mais devagar que n²=n^log_b(a). Mas f(n)=n³ cresce mais rápido — é o oposto do Caso 1.',
      B: 'Caso 2 exige f(n) = Θ(n^log_b(a)) = Θ(n²). Mas n³ ≠ Θ(n²) — n³ cresce assintoticamente mais rápido que n².',
      C: 'O resultado Θ(n³) está certo, mas o caso está errado. Caso 1 significa que as FOLHAS dominam (n^log_b(a) > f(n)). Aqui é o oposto: f(n) = n³ domina n² — isso é Caso 3.'
    }
  },
  q5: {
    correct: 'A',
    ok: 'O Teorema Mestre exige subproblemas de tamanho n/b, com b > 1 constante. Em T(n) = 2T(n−1) + 1, o subproblema tem tamanho n−1 — uma redução aditiva, não multiplicativa. O TM não se aplica. Use expansão: T(n) = 2ⁿ⁻¹ → O(2ⁿ).',
    why: {
      B: 'Não se pode aplicar o TM e dizer Caso 1 aqui. A forma T(n−1) não tem a estrutura T(n/b) necessária. O resultado real via expansão é O(2ⁿ), muito pior que O(n).',
      C: 'Caso 2 com Θ(log n) não faz sentido para T(n)=2T(n−1): a recursão dobra o número de chamadas a cada passo, o que leva a crescimento exponencial, não logarítmico.',
      D: 'Θ(2ⁿ) é o resultado CORRETO da recorrência, mas a opção diz que o TM se aplica — o que está errado. O resultado correto veio de expansão, não do TM. Não confunda o resultado com o método de obtenção.'
    }
  },
  q6: {
    correct: 'B',
