function quizAnswer(qid, el, chosen) {
  const box = document.getElementById(qid);
  if (box.dataset.answered) return;
  box.dataset.answered = '1';
  const data = QUIZ_DATA[qid];
  const correct = data.correct;
  const isOk = chosen === correct;
  box.querySelectorAll('.quiz-option').forEach(opt => {
    opt.style.pointerEvents = 'none';
    const m = opt.getAttribute('onclick').match(/'([A-F])'\)$/);
    if (m && m[1] === correct) opt.classList.add('correct');
  });
  if (!isOk) el.classList.add('wrong');
  const fb = document.getElementById(qid + '-fb');
  let html;
  if (isOk) {
    html = '<strong>✓ Correto!</strong> ' + data.ok;
    fb.className = 'quiz-feedback show ok';
  } else {
    const whyWrong = data.why[chosen] || '';
    html = '<strong>✗ Incorreto.</strong><br><br>'
      + '<strong>Por que ' + chosen + ' está errada:</strong> ' + whyWrong + '<br><br>'
      + '<strong>Por que ' + correct + ' está certa:</strong> ' + data.ok;
    fb.className = 'quiz-feedback show fail';
  }
  fb.innerHTML = html;
}

